def canon(pts,rf=False):
 pts=list(pts);forms=[]
 for k in range(8 if rf else 4):
  trans=[]
  for r,c in pts:
   if k<4: x,y=[(r,c), (c,-r),(-r,-c),(-c,r)][k]
   else: x,y=[(-r,c), (c,r),(r,-c),(-c,-r)][k-4]
   trans.append((x,y))
  mr=min(x for x,y in trans);mc=min(y for x,y in trans)
  forms.append(tuple(sorted((x-mr,y-mc) for x,y in trans)))
 return min(forms)
